import{_ as e,c as i,o as n,a0 as r}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Competition Preparation","description":"Prepare optimally for pétanque competitions. Learn the physical, mental, and tactical preparation that sets you up for peak performance.","frontmatter":{"title":"Competition Preparation","description":"Prepare optimally for pétanque competitions. Learn the physical, mental, and tactical preparation that sets you up for peak performance."},"headers":[],"relativePath":"de/blog/competition-prep.md","filePath":"de/blog/competition-prep.md"}');const t=e({name:"de/blog/competition-prep.md"},[["render",function(e,a,t,l,u,s){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="wettkampfvorbereitung" tabindex="-1">Wettkampfvorbereitung <a class="header-anchor" href="#wettkampfvorbereitung" aria-label="Permalink to &quot;Wettkampfvorbereitung&quot;">​</a></h1><p>Der Wettkampf beginnt nicht erst mit dem ersten Wurf – er beginnt Tage vorher. Wie Sie sich im Vorfeld vorbereiten, hat entscheidenden Einfluss auf Ihre Leistung. Spitzenspieler überlassen die Vorbereitung nicht dem Zufall.</p><h2 id="der-vorbereitungszeitplan" tabindex="-1">Der Vorbereitungszeitplan <a class="header-anchor" href="#der-vorbereitungszeitplan" aria-label="Permalink to &quot;Der Vorbereitungszeitplan&quot;">​</a></h2><h3 id="eine-woche-zuvor" tabindex="-1">Eine Woche zuvor <a class="header-anchor" href="#eine-woche-zuvor" aria-label="Permalink to &quot;Eine Woche zuvor&quot;">​</a></h3><p><strong>Körperliche Anforderungen:</strong></p><ul><li>Normale Trainingsintensität beibehalten</li><li>Sorgen Sie für ausreichend Ruhe.</li><li>Beheben Sie alle kleineren körperlichen Probleme.</li></ul><p><strong>Mental:</strong></p><ul><li>Visualisieren Sie eine erfolgreiche Leistung</li><li>Ziele für den Wettbewerb überprüfen</li><li>Beginnen Sie damit, Ihre Aufmerksamkeit zu fokussieren</li></ul><p><strong>Taktisch:</strong></p><ul><li>Recherchieren Sie nach Möglichkeit die Gegner.</li><li>Überprüfen Sie Ihren Spielplan</li><li>Besprechen Sie die Strategie mit Ihren Teamkollegen.</li></ul><h3 id="zwei-tage-zuvor" tabindex="-1">Zwei Tage zuvor <a class="header-anchor" href="#zwei-tage-zuvor" aria-label="Permalink to &quot;Zwei Tage zuvor&quot;">​</a></h3><p><strong>Körperliche Anforderungen:</strong></p><ul><li>Trainingsintensität reduzieren</li><li>Konzentriere dich darauf, dich wohlzufühlen, nicht darauf, dich zu verbessern.</li><li>Dem Schlaf Priorität einräumen</li></ul><p><strong>Mental:</strong></p><ul><li>Visualisierungspraxis verstärken</li><li>Nervosität vor dem Wettkampf bewältigen</li><li>Bleiben Sie positiv und zuversichtlich.</li></ul><p><strong>Logistik:</strong></p><ul><li>Ausrüstung vorbereiten</li><li>Reise und Reisezeit planen</li><li>Administrative Details erledigen</li></ul><h3 id="vortag" tabindex="-1">Vortag <a class="header-anchor" href="#vortag" aria-label="Permalink to &quot;Vortag&quot;">​</a></h3><p><strong>Körperliche Anforderungen:</strong></p><ul><li>Nur leichte Übung</li><li>Ruhe und Erholung</li><li>Gute Ernährung und ausreichende Flüssigkeitszufuhr</li></ul><p><strong>Mental:</strong></p><ul><li>Abschließende Visualisierungssitzung</li><li>Entspannungstechniken</li><li>Positives Selbstgespräch</li></ul><p><strong>Praktisch:</strong></p><ul><li>Alle Logistikvorgänge bestätigen.</li><li>Bereiten Sie vor, was Sie anziehen werden.</li><li>Alarme und Erinnerungen einstellen</li></ul><h3 id="wettkampftag" tabindex="-1">Wettkampftag <a class="header-anchor" href="#wettkampftag" aria-label="Permalink to &quot;Wettkampftag&quot;">​</a></h3><p><strong>Morgen:</strong></p><ul><li>Mit ausreichend Zeit aufwachen</li><li>Essen Sie vertraute, bewährte Lebensmittel.</li><li>Beginnen Sie mit der mentalen Vorbereitung.</li></ul><p><strong>Vor dem Spiel:</strong></p><ul><li>Früh anreisen</li><li>Sich mit dem Gelände vertraut machen</li><li>Komplettes Aufwärmprogramm</li><li>Endgültige Teamaufstellung</li></ul><h2 id="korperliche-vorbereitung" tabindex="-1">Körperliche Vorbereitung <a class="header-anchor" href="#korperliche-vorbereitung" aria-label="Permalink to &quot;Körperliche Vorbereitung&quot;">​</a></h2><h3 id="schlafen" tabindex="-1">Schlafen <a class="header-anchor" href="#schlafen" aria-label="Permalink to &quot;Schlafen&quot;">​</a></h3><p>Schlaf ist der Treibstoff für Leistung:</p><ul><li>Priorisieren Sie 7-9 Stunden in den Tagen zuvor</li><li>Halten Sie einen regelmäßigen Schlafrhythmus ein.</li><li>Vermeiden Sie Alkohol und Bildschirme vor dem Schlafengehen.</li></ul><h3 id="ernahrung" tabindex="-1">Ernährung <a class="header-anchor" href="#ernahrung" aria-label="Permalink to &quot;Ernährung&quot;">​</a></h3><p>Steigere deine Leistung:</p><ul><li>Essen Sie vertraute Speisen (keine Experimente).</li><li>Bleiben Sie hydratisiert</li><li>Vermeiden Sie schwere Mahlzeiten kurz vor dem Spielen.</li><li>Halten Sie während des Wettkampfs Snacks bereit.</li></ul><h3 id="korperliche-bereitschaft" tabindex="-1">Körperliche Bereitschaft <a class="header-anchor" href="#korperliche-bereitschaft" aria-label="Permalink to &quot;Körperliche Bereitschaft&quot;">​</a></h3><p>Seien Sie bereit, Ihren Auftritt anzunehmen:</p><ul><li>Kümmern Sie sich um alle Verletzungen oder Beschwerden.</li><li>Richtig aufwärmen</li><li>Bleibt zwischen den Spielen locker.</li></ul><h2 id="mentale-vorbereitung" tabindex="-1">Mentale Vorbereitung <a class="header-anchor" href="#mentale-vorbereitung" aria-label="Permalink to &quot;Mentale Vorbereitung&quot;">​</a></h2><h3 id="visualisierung" tabindex="-1">Visualisierung <a class="header-anchor" href="#visualisierung" aria-label="Permalink to &quot;Visualisierung&quot;">​</a></h3><p>Den Erfolg erkennen, bevor er eintritt:</p><ul><li>Visualisieren Sie konkrete Szenarien, denen Sie begegnen könnten.</li><li>Sieh dich selbst gut im Umgang mit Druck.</li><li>Spüre das Selbstvertrauen einer guten Leistung</li></ul><h3 id="zielsetzung" tabindex="-1">Zielsetzung <a class="header-anchor" href="#zielsetzung" aria-label="Permalink to &quot;Zielsetzung&quot;">​</a></h3><p>Wissen Sie, was Sie anstreben:</p><ul><li>Ergebnisziele (was Sie erreichen möchten)</li><li>Prozessziele (wie Sie vorgehen werden)</li><li>Fokussierte Ziele (wohin die Aufmerksamkeit gerichtet ist)</li></ul><h3 id="vertrauensbildung" tabindex="-1">Vertrauensbildung <a class="header-anchor" href="#vertrauensbildung" aria-label="Permalink to &quot;Vertrauensbildung&quot;">​</a></h3><p>Nimm an einem Wettbewerb teil, indem du an dich selbst glaubst:</p><ul><li>Rückblick auf vergangene Erfolge</li><li>Bestätigen Sie Ihre Vorbereitung</li><li>Konzentriere dich auf die Stärken</li></ul><h3 id="angstbewaltigung" tabindex="-1">Angstbewältigung <a class="header-anchor" href="#angstbewaltigung" aria-label="Permalink to &quot;Angstbewältigung&quot;">​</a></h3><p>Nerven produktiv kanalisieren:</p><ul><li>Angstzustände als normal ansehen</li><li>Atemtechniken anwenden</li><li>Betrachte Nervosität als Aufregung</li></ul><h2 id="taktische-vorbereitung" tabindex="-1">Taktische Vorbereitung <a class="header-anchor" href="#taktische-vorbereitung" aria-label="Permalink to &quot;Taktische Vorbereitung&quot;">​</a></h2><h3 id="kenne-dein-spiel" tabindex="-1">Kenne dein Spiel <a class="header-anchor" href="#kenne-dein-spiel" aria-label="Permalink to &quot;Kenne dein Spiel&quot;">​</a></h3><p>Machen Sie sich Ihre Vorgehensweise klar:</p><ul><li>Welchen Spielstil hat Ihr Team?</li><li>Welche Stärken können Sie nutzen?</li><li>Welche Schwächen gilt es zu beheben?</li></ul><h3 id="kenne-die-konkurrenz" tabindex="-1">Kenne die Konkurrenz <a class="header-anchor" href="#kenne-die-konkurrenz" aria-label="Permalink to &quot;Kenne die Konkurrenz&quot;">​</a></h3><p>Sammeln Sie nützliche Informationen:</p><ul><li>Tendenzen der Gegner</li><li>Geländeeigenschaften</li><li>Wettbewerbsformat und Regeln</li></ul><h3 id="habe-einen-plan" tabindex="-1">Habe einen Plan <a class="header-anchor" href="#habe-einen-plan" aria-label="Permalink to &quot;Habe einen Plan&quot;">​</a></h3><p>Mit klaren Absichten antreten:</p><ul><li>Eröffnungsstrategie</li><li>Anpassungen für verschiedene Szenarien</li><li>Rollen und Verantwortlichkeiten</li></ul><h2 id="teamvorbereitung" tabindex="-1">Teamvorbereitung <a class="header-anchor" href="#teamvorbereitung" aria-label="Permalink to &quot;Teamvorbereitung&quot;">​</a></h2><h3 id="ausrichtung" tabindex="-1">Ausrichtung <a class="header-anchor" href="#ausrichtung" aria-label="Permalink to &quot;Ausrichtung&quot;">​</a></h3><p>Stellen Sie sicher, dass alle auf dem gleichen Stand sind:</p><ul><li>Gemeinsame Ziele</li><li>Klare Rollen</li><li>Vereinbarter Kommunikationsansatz</li></ul><h3 id="unterstutzungssysteme" tabindex="-1">Unterstützungssysteme <a class="header-anchor" href="#unterstutzungssysteme" aria-label="Permalink to &quot;Unterstützungssysteme&quot;">​</a></h3><p>Gegenseitige Unterstützung einrichten:</p><ul><li>Wie werdet ihr euch gegenseitig ermutigen?</li><li>Wie werden Sie mit Rückschlägen umgehen?</li><li>Wie sieht Unterstützung aus?</li></ul><h3 id="logistik" tabindex="-1">Logistik <a class="header-anchor" href="#logistik" aria-label="Permalink to &quot;Logistik&quot;">​</a></h3><p>Praktische Angelegenheiten regeln:</p><ul><li>Reisevorbereitungen</li><li>Treffpunkte und -zeiten</li><li>Ausrüstungsverantwortung</li></ul><h2 id="das-aufwarmprogramm" tabindex="-1">Das Aufwärmprogramm <a class="header-anchor" href="#das-aufwarmprogramm" aria-label="Permalink to &quot;Das Aufwärmprogramm&quot;">​</a></h2><h3 id="korperliches-aufwarmen-15-20-minuten" tabindex="-1">Körperliches Aufwärmen (15-20 Minuten) <a class="header-anchor" href="#korperliches-aufwarmen-15-20-minuten" aria-label="Permalink to &quot;Körperliches Aufwärmen (15-20 Minuten)&quot;">​</a></h3><ol><li>Leichte Bewegung (Gehen, Armkreisen)</li><li>Dynamisches Dehnen</li><li>Allmähliches Werfen (von kurzer zu langer Distanz)</li><li>Würfe mit voller Intensität</li></ol><h3 id="mentales-aufwarmen-5-10-minuten" tabindex="-1">Mentales Aufwärmen (5-10 Minuten) <a class="header-anchor" href="#mentales-aufwarmen-5-10-minuten" aria-label="Permalink to &quot;Mentales Aufwärmen (5-10 Minuten)&quot;">​</a></h3><ol><li>Schwerpunktverlagerung auf den Wettbewerb</li><li>Kurze Visualisierung</li><li>Positives Selbstgespräch</li><li>Absichtsbildung</li></ol><h3 id="gelandeerkundung" tabindex="-1">Geländeerkundung <a class="header-anchor" href="#gelandeerkundung" aria-label="Permalink to &quot;Geländeerkundung&quot;">​</a></h3><ol><li>Betrachten Sie die Spielfläche</li><li>Notieren Sie alle Unregelmäßigkeiten.</li><li>Testen Sie nach Möglichkeit verschiedene Bereiche.</li><li>Besprechen Sie Ihre Beobachtungen mit dem Team.</li></ol><h2 id="haufige-vorbereitungsfehler" tabindex="-1">Häufige Vorbereitungsfehler <a class="header-anchor" href="#haufige-vorbereitungsfehler" aria-label="Permalink to &quot;Häufige Vorbereitungsfehler&quot;">​</a></h2><h3 id="ubertraining" tabindex="-1">Übertraining <a class="header-anchor" href="#ubertraining" aria-label="Permalink to &quot;Übertraining&quot;">​</a></h3><p>Der Versuch, sich in den letzten Tagen noch zu verbessern, führt zu Erschöpfung, nicht zu Leistungssteigerungen.</p><h3 id="unterschlafen" tabindex="-1">Unterschlafen <a class="header-anchor" href="#unterschlafen" aria-label="Permalink to &quot;Unterschlafen&quot;">​</a></h3><p>Für zusätzliches Training auf Schlaf zu verzichten, rächt sich.</p><h3 id="neue-experimente" tabindex="-1">Neue Experimente <a class="header-anchor" href="#neue-experimente" aria-label="Permalink to &quot;Neue Experimente&quot;">​</a></h3><p>Der Wettkampftag ist nicht dazu da, neue Techniken oder Ausrüstung auszuprobieren.</p><h3 id="nerven-ignorieren" tabindex="-1">Nerven ignorieren <a class="header-anchor" href="#nerven-ignorieren" aria-label="Permalink to &quot;Nerven ignorieren&quot;">​</a></h3><p>So zu tun, als sei man nicht nervös, hilft nicht. Man muss die Nervosität anerkennen und damit umgehen.</p><h3 id="mangelhafte-logistik" tabindex="-1">Mangelhafte Logistik <a class="header-anchor" href="#mangelhafte-logistik" aria-label="Permalink to &quot;Mangelhafte Logistik&quot;">​</a></h3><p>Übereiltes Handeln aufgrund mangelhafter Planung erzeugt unnötigen Stress.</p><h2 id="die-nacht-zuvor" tabindex="-1">Die Nacht zuvor <a class="header-anchor" href="#die-nacht-zuvor" aria-label="Permalink to &quot;Die Nacht zuvor&quot;">​</a></h2><h3 id="tun" tabindex="-1">Tun: <a class="header-anchor" href="#tun" aria-label="Permalink to &quot;Tun:&quot;">​</a></h3><ul><li>Bereiten Sie alles vor, was Sie benötigen</li><li>Gehen Sie zur gewohnten Zeit ins Bett.</li><li>Wenden Sie bei Bedarf Entspannungstechniken an.</li><li>Vertraue deiner Vorbereitung.</li></ul><h3 id="nicht" tabindex="-1">Nicht: <a class="header-anchor" href="#nicht" aria-label="Permalink to &quot;Nicht:&quot;">​</a></h3><ul><li>Lange wach bleiben und sich Sorgen machen</li><li>Strategie überanalysieren</li><li>Verzichten Sie auf Alkohol oder schwere Speisen.</li><li>Nehmen Sie an stressigen Aktivitäten teil.</li></ul><h2 id="wettbewerbsvormittag" tabindex="-1">Wettbewerbsvormittag <a class="header-anchor" href="#wettbewerbsvormittag" aria-label="Permalink to &quot;Wettbewerbsvormittag&quot;">​</a></h2><h3 id="routineangelegenheiten" tabindex="-1">Routineangelegenheiten <a class="header-anchor" href="#routineangelegenheiten" aria-label="Permalink to &quot;Routineangelegenheiten&quot;">​</a></h3><p>Halten Sie sich an bewährte Muster:</p><ul><li>Zum geplanten Zeitpunkt aufwachen</li><li>Iss bewährte Lebensmittel</li><li>Folgen Sie Ihrer gewohnten Morgenroutine.</li><li>Planen Sie genügend Zeit ein.</li></ul><h3 id="geisteszustand" tabindex="-1">Geisteszustand <a class="header-anchor" href="#geisteszustand" aria-label="Permalink to &quot;Geisteszustand&quot;">​</a></h3><p>Die richtige Denkweise entwickeln:</p><ul><li>Aufgeregt, nicht ängstlich</li><li>Selbstbewusst, nicht arrogant</li><li>Konzentriert, nicht angespannt</li><li>Bereit, nicht verzweifelt</li></ul><h2 id="ankunft-am-veranstaltungsort" tabindex="-1">Ankunft am Veranstaltungsort <a class="header-anchor" href="#ankunft-am-veranstaltungsort" aria-label="Permalink to &quot;Ankunft am Veranstaltungsort&quot;">​</a></h2><ol><li><strong>Einrichten</strong>: Finden Sie Ihren Platz, organisieren Sie Ihre Ausrüstung</li><li><strong>Beobachten Sie:</strong> Betrachten Sie das Gelände und notieren Sie die Bedingungen.</li><li><strong>Aufwärmen</strong>: Absolvieren Sie Ihr Trainingsprogramm.</li><li><strong>Verbindung</strong>: Kurze Teamabstimmung</li><li><strong>Fokus</strong>: Abschließende mentale Vorbereitung</li></ol><p>Du hast dich gut vorbereitet. Vertraue jetzt darauf und tritt an.</p><hr><p>| <em>Verwandt: <a href="/en/education/training/">Trainingsmethoden</a> | <a href="/en/education/mental-strength/handling-pressure">Umgang mit Druck</a> | <a href="/en/education/mental-strength/pre-shot-routine">Vorbereitungsroutine vor der Impfung</a></em> |</p>',107)])])}]]);export{a as __pageData,t as default};
